     1→import { useState } from "react";
     2→import { Alert } from "react-native";
     3→import * as Location from "expo-location";
     4→import { Waypoint, Coordinate } from "@types/Route";
     5→import { TProps, TController } from "./types";
     6→
     7→export const useController = ({
     8→  waypoints,
     9→  onAddWaypoint,
    10→  onDeleteWaypoint,
    11→}: TProps): TController => {
    12→  const [showAddModal, setShowAddModal] = useState(false);
    13→  const [selectedCoordinate, setSelectedCoordinate] =
    14→    useState<Coordinate | null>(null);
    15→  const [waypointName, setWaypointName] = useState("");
    16→  const [region, setRegion] = useState({
    17→    latitude: 37.78825,
    18→    longitude: -122.4324,
    19→    latitudeDelta: 0.0922,
    20→    longitudeDelta: 0.0421,
    21→  });
    22→
    23→  const getCurrentLocation = async () => {
    24→    try {
    25→      const { status } = await Location.requestForegroundPermissionsAsync();
    26→      if (status !== "granted") {
    27→        Alert.alert("Permission denied", "Location permission is required");
    28→        return;
    29→      }
    30→
    31→      const location = await Location.getCurrentPositionAsync({});
    32→      const newRegion = {
    33→        latitude: location.coords.latitude,
    34→        longitude: location.coords.longitude,
    35→        latitudeDelta: 0.01,
    36→        longitudeDelta: 0.01,
    37→      };
    38→      setRegion(newRegion);
    39→      setSelectedCoordinate({
    40→        latitude: location.coords.latitude,
    41→        longitude: location.coords.longitude,
    42→      });
    43→    } catch (error) {
    44→      console.error("Error getting location:", error);
    45→    }
    46→  };
    47→
    48→  const handleMapPress = (event: any) => {
    49→    const coordinate = event.nativeEvent.coordinate;
    50→    setSelectedCoordinate(coordinate);
    51→  };
    52→
    53→  const handleAddWaypoint = () => {
    54→    if (!selectedCoordinate) {
    55→      Alert.alert("Error", "Please select a location on the map");
    56→      return;
    57→    }
    58→
    59→    const newWaypoint: Omit<Waypoint, "id"> = {
    60→      coordinate: selectedCoordinate,
    61→      name: waypointName.trim() || undefined,
    62→      timestamp: Date.now(),
    63→    };
    64→
    65→    onAddWaypoint(newWaypoint);
    66→    setShowAddModal(false);
    67→    setWaypointName("");
    68→    setSelectedCoordinate(null);
    69→  };
    70→
    71→  const handleDeleteWaypoint = (id: string) => {
    72→    Alert.alert(
    73→      "Delete Waypoint",
    74→      "Are you sure you want to delete this waypoint?",
    75→      [
    76→        { text: "Cancel", style: "cancel" },
    77→        {
    78→          text: "Delete",
    79→          style: "destructive",
    80→          onPress: () => onDeleteWaypoint(id),
    81→        },
    82→      ]
    83→    );
    84→  };
    85→
    86→  return {
    87→    showAddModal,
    88→    selectedCoordinate,
    89→    waypointName,
    90→    region,
    91→    handleMapPress,
    92→    handleAddWaypoint,
    93→    handleDeleteWaypoint,
    94→    setShowAddModal,
    95→    setWaypointName,
    96→    getCurrentLocation,
    97→  };
    98→};
